-- Hand-written rules -------------------------------------------------------

ALTER TABLE accounting.tax_code
  ADD CONSTRAINT tax_code_code_valid CHECK (code ~ '^[A-Z0-9][A-Z0-9_-]{0,14}$');
ALTER TABLE accounting.tax_rate
  ADD CONSTRAINT tax_rate_range CHECK (rate_pct >= 0 AND rate_pct <= 100);
ALTER TABLE workshop.labour_rate
  ADD CONSTRAINT labour_rate_positive CHECK (rate > 0);
ALTER TABLE workshop.pricing_settings
  ADD CONSTRAINT pricing_discount_limit_range CHECK (manager_discount_limit_pct >= 0 AND manager_discount_limit_pct <= 100);
ALTER TABLE org.company_logo
  ADD CONSTRAINT company_logo_size CHECK (width BETWEEN 1 AND 600 AND height BETWEEN 1 AND 300);

-- The tax account is a liability posting account (checked when set); codes never change.
CREATE OR REPLACE FUNCTION accounting.guard_tax_code_account() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.output_account_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM accounting.account a
        WHERE a.id = NEW.output_account_id AND a.company_id = NEW.company_id
          AND a.type = 'liability' AND a.is_posting AND a.status = 'active') THEN
    RAISE EXCEPTION 'tax_code_account_invalid' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.code <> OLD.code THEN
    RAISE EXCEPTION 'tax_code_code_immutable' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER tax_code_account BEFORE INSERT OR UPDATE ON accounting.tax_code
  FOR EACH ROW EXECUTE FUNCTION accounting.guard_tax_code_account();

-- Dated rates (tax and labour) are history: never updated; only a rate that has not started yet
-- may be removed. Documents will keep the rate they used.
CREATE OR REPLACE FUNCTION platform.guard_dated_rate() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'dated_rate_immutable' USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.effective_from <= CURRENT_DATE THEN
    RAISE EXCEPTION 'dated_rate_in_effect' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN OLD;
END;
$$;
CREATE TRIGGER tax_rate_history BEFORE UPDATE OR DELETE ON accounting.tax_rate
  FOR EACH ROW EXECUTE FUNCTION platform.guard_dated_rate();
CREATE TRIGGER labour_rate_history BEFORE UPDATE OR DELETE ON workshop.labour_rate
  FOR EACH ROW EXECUTE FUNCTION platform.guard_dated_rate();

-- The default tax code is an active one, and stays active while it is the default.
CREATE OR REPLACE FUNCTION accounting.guard_tax_default() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.default_tax_code_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM accounting.tax_code t WHERE t.id = NEW.default_tax_code_id AND t.active) THEN
    RAISE EXCEPTION 'tax_default_inactive' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER tax_settings_default BEFORE INSERT OR UPDATE ON accounting.tax_settings
  FOR EACH ROW EXECUTE FUNCTION accounting.guard_tax_default();
CREATE OR REPLACE FUNCTION accounting.guard_tax_code_default() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.active AND NOT NEW.active
     AND EXISTS (SELECT 1 FROM accounting.tax_settings s WHERE s.default_tax_code_id = NEW.id) THEN
    RAISE EXCEPTION 'tax_code_is_default' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER tax_code_default BEFORE UPDATE ON accounting.tax_code
  FOR EACH ROW EXECUTE FUNCTION accounting.guard_tax_code_default();

-- ── permissions: company administrators receive the new ones (as new companies do) ────────────
UPDATE iam.role
   SET permissions = (
         SELECT array_agg(DISTINCT p ORDER BY p)
           FROM unnest(permissions || ARRAY['org.company.manage', 'accounting.tax.manage',
                                            'workshop.pricing.manage']) AS p),
       version = version + 1,
       updated_at = now()
 WHERE is_system AND code = 'company-admin';
